-- ============================================================================
-- LOUEURS (annuaire) -> fiches VITRINE dans NEXUS Location (is_rental), attribuees
-- a l'ADMIN. Categorie deduite du nom, prix « sur devis » (pas de price_per_day donc
-- aucune ligne de prix affichee), vrai telephone visible dans specs.condition.
-- Genere depuis prospection/loueurs_materiel_senegal.csv. Idempotent.
-- ============================================================================

do $$ begin
  if not exists (select 1 from public.profiles where role='admin') then
    raise exception 'Aucun compte admin (profiles.role=admin).';
  end if;
end $$;

drop table if exists _loueurs;
create temp table _loueurs(name text, category text, description text, vendor_name text, rental_specs jsonb);

with adm as (select id from public.profiles where role='admin' order by created_at asc limit 1)
select l.name,l.category,1,1,l.description,(select id from adm),l.vendor_name,true,true,l.rental_specs
  from _loueurs l
 where not exists (select 1 from public.products p where p.vendor_id=(select id from adm) and p.name=l.name and coalesce(p.is_rental,false)=true);

select 'loueurs_vitrine' as type, count(*) as n from _loueurs;
